function def = f90_xfluid04_definition
%F90_XFLUID04_DEFINITION Closed-loop electrohydraulic lift task contract.

def = struct;
def.id = "XFLUID04";
def.formal_id = "F90-XFLUID-04";
def.reference_role = "benchmark_reference";
def.sim = struct("start",0,"stop",20,"max_step",0.02, ...
    "initial_extension_mm",50);
def.source = struct( ...
    "url","https://github.com/mathworks/Simscape-Hydraulic-Lift", ...
    "tag","25.1.3.6", ...
    "commit","2e716625c062fa642f8fd954663ca85e7c87fac0", ...
    "license","BSD-3-Clause", ...
    "project","Hydraulic_Lift.prj", ...
    "exact_model","ssc_hydraulic_lift.slx", ...
    "exact_file_presence","present");

taskRoot = string(getenv("SIMUVERITY_TASK_ROOT"));
def.runner = struct( ...
    "builder","f90_xfluid04_build_reference", ...
    "scorer","f90_xfluid04_score_model", ...
    "reference_model",taskRoot + "/reference/XFLUID04_reference.slx", ...
    "public_spec",taskRoot + "/public/XFLUID04.json", ...
    "official_scenarios",taskRoot + "/official/XFLUID04.json");

def.public_inputs = [ ...
    pin("lift_target_mm",120,90,145,"mm", ...
        "upper extension target of the hydraulic actuator"), ...
    pin("motion_start_s",1.5,1.0,2.0,"s", ...
        "time at which the smooth raise trajectory begins"), ...
    pin("ramp_duration_s",4.0,3.0,5.0,"s", ...
        "duration of each linear raise or return segment"), ...
    pin("target_hold_s",5.0,4.0,6.0,"s", ...
        "time for which the upper extension target is held"), ...
    pin("supply_pressure_bar",200,160,230,"bar", ...
        "hydraulic supply pressure before the in-run change"), ...
    pin("supply_pressure_step_fraction",-0.08,-0.18,0.12,"1", ...
        "fractional in-run change of hydraulic supply pressure"), ...
    pin("pressure_step_offset_s",2.0,1.0,3.0,"s", ...
        "time from reaching the upper target to the pressure change")];

def.outputs = [ ...
    pout("actuator_extension",1,"mm", ...
        "extension measured by a physical translational-motion sensor across the cylinder"), ...
    pout("actuator_velocity",1,"mm/s", ...
        "velocity measured by the same physical cylinder-motion sensor"), ...
    pout("valve_spool_position",1,"mm", ...
        "physical displacement measured at the metering-valve spool")];

def.prompt = strjoin([ ...
    "Build a closed-loop electrohydraulic scissor lift that raises, holds, and returns a payload platform using one double-acting hydraulic actuator.", ...
    "A finite pressure supply and return reservoir must feed a physically metered four-way valve. A finite electromechanical actuator must move the valve element, the valve must route real fluid into and out of both cylinder chambers, and the cylinder must drive a scissor linkage carrying the platform. Measured cylinder extension must close the positioning loop through unrestricted control logic to the real valve actuator on this same hydraulic power path.", ...
    "The actuator starts near 50 mm extension. Read lift_target_mm, motion_start_s, ramp_duration_s, target_hold_s, supply_pressure_bar, supply_pressure_step_fraction, and pressure_step_offset_s from MATLAB base-workspace variables. Their nominal values are 120 mm, 1.5 s, 4.0 s, 5.0 s, 200 bar, -0.08, and 2.0 s. Their valid ranges are 90--145 mm, 1.0--2.0 s, 3.0--5.0 s, 4.0--6.0 s, 160--230 bar, -0.18--0.12, and 1.0--3.0 s.", ...
    "Beginning at motion_start_s, command a linear raise from 50 mm to lift_target_mm over ramp_duration_s, hold that target for target_hold_s, then command a linear return to 50 mm over ramp_duration_s. During the hold, at pressure_step_offset_s after first reaching the target, change the supply pressure from supply_pressure_bar to supply_pressure_bar*(1+supply_pressure_step_fraction).", ...
    "Across the declared target, timing, and supply-pressure ranges, the controller must follow the full positioning cycle without sustained oscillation, keep cylinder and valve motion bounded, and preserve tracking through the pressure change. The supply-pressure input must act in the real hydraulic path. Prescribed motion, copied command outputs, signal-only hydraulic surrogates, and a cylinder disconnected from the scissor load are not valid implementations.", ...
    "Log Timeseries actuator_extension with one channel in millimetres, actuator_velocity with one channel in millimetres per second, and valve_spool_position with one channel in millimetres. All three must originate from physical motion in the cylinder or valve mechanism.", ...
    "Work directly in the required model file and keep the latest usable state saved at that path throughout the task."], sprintf("\n\n"));

def.scenarios = [ ...
    scenario("low_supply_drop", values(135,1.2,4.8,5.5,160,-.12,2.0)), ...
    scenario("high_supply_rise", values(95,1.8,3.5,4.5,230,.08,1.5)), ...
    scenario("high_target_boundary", values(143,1.0,5.0,5.0,175,-.10,2.5)), ...
    scenario("pressure_drop_pair", values(118,1.5,4.0,5.0,190,-.15,2.0)), ...
    scenario("pressure_control_pair", values(118,1.5,4.0,5.0,190,0,2.0))];

def.groups = struct( ...
    "G","runnable model, physical Timeseries contract, closed loop and pressure-causal core path", ...
    "A","nominal full-cycle extension tracking accuracy", ...
    "Q","nominal positioning and actuator/valve motion quality", ...
    "M","hydraulic, electromechanical, cylinder, scissor, feedback and pressure causality", ...
    "R","worst required target/timing/pressure operating point", ...
    "D","paired in-run supply-pressure-change response and recovery", ...
    "weights",struct("A",.22,"Q",.16,"M",.24,"R",.23,"D",.15));
end

function s = pin(name, nominal, minv, maxv, unit, meaning)
s = struct("name",name,"nominal",nominal,"min",minv,"max",maxv, ...
    "unit",unit,"meaning",meaning);
end

function s = pout(name, channels, unit, source)
s = struct("name",name,"channels",channels,"unit",unit, ...
    "physical_source",source);
end

function s = scenario(id, scenarioValues)
s = struct("id",id,"values",scenarioValues);
end

function v = values(target,startTime,rampTime,holdTime,pressure,step,offset)
v = struct( ...
    "lift_target_mm",target, ...
    "motion_start_s",startTime, ...
    "ramp_duration_s",rampTime, ...
    "target_hold_s",holdTime, ...
    "supply_pressure_bar",pressure, ...
    "supply_pressure_step_fraction",step, ...
    "pressure_step_offset_s",offset);
end
